<P>p. 17<br>
GLOSSARY<br>
abaxial. Side or surface of a structure away from the axis distal to the point at which the structure is borne (e.g., lower surface of a leaf, outer surface of a petal). (see adaxial)<br>
 'away from the axis on which the structure' made 'away from the axis distal to the point at which the structure'<br>
2012 07 12<br>
<P>p. 17<br>
GLOSSARY<br>
adaxial. Side or surface of a structure toward the axis distal to the point at which the structure is borne (e.g., upper surface of a leaf, inner surface of a petal). (see abaxial)<br>
 'toward the axis on which the structure' made 'toward the axis distal to the point at which the structure'<br>
2012 07 12<br>
<P>p. 17<br>
GLOSSARY<br>
acuminate. Having a long-tapered, sharp tip, the sides concave. (see acute, attenuate, awl-like)<br>
 '(see acute, awl-like)' made '(see acute, attenuate, awl-like)'<br>
2014 05 13<br>
<P>p. 17<br>
GLOSSARY<br>
acute. Having a short-tapered, sharp tip, the sides convex or straight and converging at less than a right angle. (see acuminate, attenuate, awl-like, obtuse)<br>
 '(see acuminate, obtuse)' made '(see acuminate, attenuate, awl-like, obtuse)<br>
2014 05 13<br>
<P>p. 18<br>
GLOSSARY<br>
aquatic. Growing under, in, or on water (generally fresh; if brackish, saline, or marine, so indicated), whether rooted in bottom or floating, and including plants with parts of shoots submersed but with other parts above water (e.g., <em>Potamogeton gramineus</em>); excluding plants of seeps or wet rocks. (see emersed, submersed)<br>
 '(e.g., <em>Potamogeton gramineus</em>)' moved<br>
2012 03 27<br>
<P>p. 18<br>
GLOSSARY<br>
attenuate. Having a long-tapered, sharp tip. (see acuminate, acute, awl-like)<br>
 'attenuate. Having a long-tapered, sharp tip. (see acuminate, acute, awl-like)' added to glossary<br>
2014 05 13<br>
<P>p. 18<br>
GLOSSARY<br>
awl-like. Narrow throughout, but broader at the base and tapered to a sharp tip. (see acuminate, acute, attenuate)<br>
 '(see acuminate)' made '(see acuminate, acute, attenuate)'<br>
2014 05 13<br>
<P>p. 22<br>
GLOSSARY<br>
ellipsoid. In the shape of a flattened or elongated sphere, widest at the middle and tapered equally to both ends, as a fruit; wider than linear. (see elliptic, linear, oblong)<br>
 'circle' made 'sphere'; 'in three dimensions,' deleted<br>
2012 03 27<br>
<P>p. 22<br>
GLOSSARY<br>
elliptic. In the shape of a flattened or elongated circle, widest at the middle and tapered equally to both ends, as a leaf; wider than linear. (see ellipsoid, linear, oblong)<br>
 'in two dimensions (i.e., in one plane),' deleted<br>
2012 03 27<br>
<P>p. 24<br>
GLOSSARY<br>
infraspecific. Below the species level or within a species; pertaining to variation within a species, whether taxonomically significant (e.g., characterizing subspecies or varieties) or not (e.g., characterizing forms or minor variants).<br>
 'i.e.' made 'e.g.'<br>
2012 03 27<br>
<P>p. 25<br>
GLOSSARY<br>
leaflet. Leaf-like unit of a compound leaf; distinguished from a leaf by the absence in its axil of a bud, branch, thorn, or flower; either simple (leaf 1-compound, with 1&deg; leaflets) or compound (leaf 2-compound, with 1&deg; and 2&deg; leaflets; 3-compound, with 1&deg;, 2&deg;, and 3&deg; leaflets; etc.).<br>
 comma made semicolon before 'etc.' near end [made on 2012 03 27]<br>
 'lacking lateral, basal appendages (stipules);' deleted, after '.branch, thorn, or flower;'<br>
2013 08 09 [in addition to change(s) made on 2012 03 27, above]<br>
<P>p. 27<br>
GLOSSARY<br>
mericarp. One of the generally dry, generally indehiscent, 1&ndash;few-seeded, 1-carpelled segments into which certain fruits separate at maturity (e.g., those of Apiaceae).<br>
 deleted &plusmn; repeated phrase '(generally dry, indehiscent, 1-seeded)'<br>
2012 03 27<br>
<P>p. 28<br>
GLOSSARY<br>
ocrea, ochrea (ocreae, ochreae). In Polygonaceae, generally scarious sheath around the stem formed by the fusion of stipules.<br>
 'ocrea (ocreae).' made 'ocrea, ochrea (ocreae, ochreae).'<br>
2013 02 26<br>
<P>p. 28<br>
GLOSSARY<br>
papillate. Pertaining to a surface (e.g., of a leaf, stigma, fruit) bearing small, rounded or conic protuberances (papillae; singular papilla).<br>
 deleted comma after 'rounded'<br>
2012 03 27<br>
<P>p. 30<br>
GLOSSARY<br>
pome. In Rosaceae, a fleshy, indehiscent fruit, such as an apple or pear; derived from a hypanthium (represented as outer fleshy material and skin) surrounding and &plusmn; fused to a compound ovary (represented as (1)2&ndash;5 papery-walled, radiating segments alternating with fleshy material, as in, e.g., <em>Amelanchier utahensis</em> fruit) or to (1)2&ndash;5 free ovaries, each with a &plusmn; stony outer layer. (see berry, drupe)<br>
 moved 'e.g., <em>Amelanchier utahensis</em> fruit'; added 'as in'<br>
2012 03 27<br>
<P>p. 30<br>
GLOSSARY<br>
prickle. Sharp-pointed, stiff or somewhat flexible projection, originating at or near the surface and neither subtending an axillary bud or branch nor subtended by a leaf or leaf scar, without leaves, leaf scars, buds, or branches (e.g., <em>Rosa woodsii</em> stem); loosely used for any sharp projection. (see armed, spine, thorn)<br>
 moved '(e.g., <em>Rosa woodsii</em> stem)'<br>
2012 03 27<br>
<P>p. 31<br>
GLOSSARY<br>
radiant head. In Asteraceae, a discoid head with a peripheral ring of flowers having much enlarged, often bilateral corollas.<br>
 '(p. 31)' deleted [in TJM2; page numbers not used, illustrations not presented, in eFlora]<br>
2014 04 14<br>
<P>p. 31<br>
GLOSSARY<br>
radiate head. (p. 31) In Asteraceae, a head composed of central disk flowers and marginal ray flowers. (see disciform head, discoid head, liguliflorous head, radiant head)<br>
 '(p. 25)' made '(p. 31)' [in TJM2; page numbers not used, illustrations not presented, in eFlora]<br>
2014 04 14<br>
<P>p. 32<br>
GLOSSARY<br>
spine. Sharp-pointed, usually stiff projection, derived from a leaf or leaf part (e.g., stipule, vein tip), and therefore often subtending an axillary bud or branch, without buds of its own (e.g., <em>Cirsium arvense</em> leaf); loosely used for any sharp projection. (see armed, prickle, thorn)<br>
 moved '(e.g., <em>Cirsium arvense</em> leaf)' [change made on 2012 03 27]<br>
 'originating below the epidermis,' deleted, after 'usually stiff projection,'<br>
 '(e.g., <em>Cirsium arvense</em> leaf)' made '(e.g., marginal spine of <em>Cirsium arvense</em> leaf)'<br>
2013 08 09 [in addition to change(s) made on 2012 03 27, above]<br>
<P>p. 33<br>
GLOSSARY<br>
stipe. 1. In ferns, a leaf stalk (analogous to a petiole of a leaf), connecting blade to rhizome. 2. In some Polygonaceae, a stalk-like base of a flower or of a hypanthium, distal to pedicel (stipe and pedicel separated by line of dehiscence or a bulge, or differences in thickness; if no such demarcation exists, the structure throughout is a pedicel, not in part a stipe).<br>
 '1.' inserted before 'In ferns', definition 2. added [change made on 2012 07 16]<br>
 'a stalk-like flower or hypanthium base' made 'a stalk-like base of a flower or of a hypanthium'<br>
2013 08 09 [in addition to change(s) made on 2012 07 16, above]<br>
<P>p. 33<br>
GLOSSARY<br>
thorn. Sharp-pointed, usually stiff projection, derived from a branch and therefore often subtended by a leaf or leaf scar, sometimes with leaf scars and buds of its own (e.g., <em>Castela emoryi</em>); loosely used for any sharp projection. (see armed, prickle, spine)<br>
 moved '(e.g., <em>Castela emoryi</em>)' [change made on 2012 03 27]<br>
 'originating below the epidermis,' deleted, after 'usually stiff projection,'<br>
2013 08 09 [in addition to change(s) made on 2012 03 27, above]<br>
<P>p. 34<br>
GLOSSARY<br>
utricle. Mostly dry, dehiscent or indehiscent fruit from a generally compound pistil in which a balloon- or bladder-like ovary wall loosely encloses (or, in some Chenopodiaceae, is adherent to) a single seed.<br>
 'Amaranthaceae' made 'Chenopodiaceae'<br>
2013 09 26<br>
<P>p. 34<br>
GLOSSARY<br>
valve. 1. In legumes or capsules opening by longitudinal lines, one of the parts into which the fruit is dehiscent (such fruits valvate). 2. In anthers, the flap of tissue resulting from dehiscence by a curved line (e.g., Lauraceae, some Berberidaceae). 3. In Ophioglossaceae, one of the parts into which the sporangium is dehiscent.<br>
 period added before '3.'<br>
2012 03 27<br>
<P>p. 34<br>
GLOSSARY<br>
vein. 1. Tissue specialized for transport of substances within a plant: water and dissolved inorganic substances (e.g., mineral nutrients) through the xylem; energy-rich, organic compounds (products of photosynthesis) through the phloem. 2. Strand of such tissue, often seen as a line in surface view and as a bundle in transverse section.<br>
 comma made semicolon after 'xylem'<br>
2012 03 27<br>
<P>p. 38<br>
Klamath Ranges Subregion (KR). In the east, the boundary between the predominantly metamorphic KR and the volcanic CaR lies east and north of Shasta Lake, incorporating the McCloud and Hosselkus limestone formations. In the southeast, the boundary generally excludes the chaparral and foothill-pine/blue-oak woodland vegetation of the Inner North Coast Ranges District (NCoRI) in southwestern Shasta and northwestern Tehama counties.<br>
 'In the east, the boundary between the predominantly metamorphic KR and the volcanic CaR is interpreted to be near Interstate 5. In the southeast, the boundary generally excludes the chaparral and pine/oak woodland vegetation of the Inner North Coast Ranges District (NCoRI) in western Shasta and Tehama counties.' made 'In the east, the boundary between the predominantly metamorphic KR and the volcanic CaR lies east and north of Shasta Lake, incorporating the McCloud and Hosselkus limestone formations. In the southeast, the boundary generally excludes the chaparral and foothill-pine/blue-oak woodland vegetation of the Inner North Coast Ranges District (NCoRI) in southwestern Shasta and northwestern Tehama counties.'<br>
2016 01 26<br>
<P>p. 38<br>
CASCADE RANGES REGION (CaR). This region, characterized by volcanics, is bounded to the north by Oregon, to the west by the predominantly metamorphic KR, to the southwest by agricultural land or grassland of the GV, to the southeast by the Sierra Nevada Region (SN), and to the east by the juniper woodland of the GB.<br>
 'This region, characterized by volcanics, is bounded to the north by Oregon, to the west by the pre- dominantly metamorphic KR (generally along Interstate 5) and NCoRI (along the Sacramento River between Redding and Red Bluff), to the southwest by agricultural land or grassland of the GV, to the southeast by the Sierra Nevada Region (SN), and to the east by the juniper woodland of the GB.' made 'This region, characterized by volcanics, is bounded to the north by Oregon, to the west by the predominantly metamorphic KR, to the southwest by agricultural land or grassland of the GV, to the southeast by the Sierra Nevada Region (SN), and to the east by the juniper woodland of the GB.'<br>
2016 01 26<br>
<P>p. 39<br>
Cascade Range Foothills Subregion (CaRF).  This subregion, in the southwestern part of CaR, is characterized by chaparral and blue-oak/foothill-pine woodland at about 100&ndash;500 m in elevation. The northern CaRF and northern NCoRI combined with the southern KR form a continuous horseshoe-shaped band of similar foothill vegetation along the northern margin of the GV.<br>
 'This subregion, in the southwestern part of CaR, is characterized by chaparral and blue-oak/foothill-pine woodland at about 100&ndash;500 m in elevation. The CaRF and the adjacent NCoRI and northern Sierra Nevada Foothills District (n SNF) comprise a horseshoe-shaped area of similar foothill vegetation around the northern boundaries of the GV.' made 'This subregion, in the southwestern part of CaR, is characterized by chaparral and blue-oak/foothill-pine woodland at about 100&ndash;500 m in elevation. The northern CaRF and northern NCoRI combined with the southern Kr form a continuous horseshoe-shaped band of similar foothill vegetation along the northern margin of the GV.'<br>
2016 01 26<br>
