[pertaining to note:] Ashy-gray, pale, chaffy-bracted, puberulent pls of ne Siskiyou Co. that have been identified as <em>M. odoratissima</em> subsp. <em>o.</em> intergrade or are intermediate in morphology between subspecies <em>glauca</em> and <em>pallida</em>; if recognized taxonomically, pls in NCoRH with spreading, soft, wavy lf hairs (and highly variable bract morphology) assignable to <em>Monardella odoratissima</em> subsp. <em>pinetorum</em> (Heller) Epling (study needed).<br>
