<P>p. 912 [location or approximate location where note would appear in TJM2 were it not unabridged and therefore only in eFlora]<br>
MYRSINACEAE<br>
[pertaining to unabridged note:] Recent molecular work has redefined Ericales. Non-rosette, terrestrial members of Primulaceae s.l. are now widely treated in Myrsinoideae or Myrsinaceae, which are further characterized by synapomorphies of dark dots or streaks on stems, leaves, or flowers, short corolla tubes, seeds immersed in the placenta, and &ndash; for woody members &ndash; wood lacking rays or with only multiseriate rays. Primulaceae, Myrsinaceae, Theophrastaceae, and Maesaceae (a recent segregate of tropical trees) constitute a closely related, monophyletic group. <em>Lysimachia</em> has been recognized (even by Linnaeus) as a rather complex group with close affinities to other genera (<em>Glaux</em>, for instance, has been shown to be an apetalous sp. of <em>Lysimachia</em>). Phylogenetic research (by Arne A. Anderberg and colleagues in Europe) on this and related genera indicated that they were actually specialized taxa that had evolved within <em>Lysimachia</em>, so that all California members of Myrsinaceae now have been transferred to <em>Lysimachia</em> (Manns & Anderberg 2009 Willdenowia 39:49&ndash;54 and Cholewa 2014 Phytoneuron 2014-28: 1&ndash;2), as reflected in this revised treatment that now includes <em>Lysimachia arvensis</em>, <em>Lysimachia europaea</em>, <em>Lysimachia latifolia</em>, <em>Lysimachia maritima</em>, <em>Lysimachia minima</em>, and <em>Lysimachia monelli</em>, in addition to the two species previously treated in the genus.<br>
 'this revised treatment that now includes <em>Lysimachia arvensis</em>, <em>Lysimachia europaea</em>, <em>Lysimachia latifolia</em>, <em>Lysimachia maritima</em>, and <em>Lysimachia minima</em>.' made 'this revised treatment that now includes <em>Lysimachia arvensis</em>, <em>Lysimachia europaea</em>, <em>Lysimachia latifolia</em>, <em>Lysimachia maritima</em>, <em>Lysimachia minima</em>, and <em>Lysimachia monelli</em>, in addition to the two species previously treated in the genus.' [not abbreviated in eFlora]<br>
2015 02 05<br>
